import{_ as o,C as s,o as t,c as r,a2 as a,b as l,w as i,a as d,E as c,a3 as u}from"./chunks/framework.CRkDNIZq.js";const f=JSON.parse('{"title":"14.1 Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-and-estimation.md","filePath":"system-design/14.1-requirements-and-estimation.md"}'),m={name:"system-design/14.1-requirements-and-estimation.md"};function g(h,e,p,y,b,x){const n=s("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="_14-1-requirements-capacity-estimation" tabindex="-1">14.1 Requirements &amp; Capacity Estimation <a class="header-anchor" href="#_14-1-requirements-capacity-estimation" aria-label="Permalink to &quot;14.1 Requirements &amp; Capacity Estimation&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Requirements analysis defines the exact operational contract of the software: what features it must deliver (functional) and what performance, availability, and durability guarantees it must maintain (non-functional). Capacity estimation applies back-of-the-envelope arithmetic to calculate bandwidth, CPU, memory, and disk storage growth over time.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How This Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How This Project Uses It&quot;">​</a></h2><p>In <code>SPEC.txt</code> and <code>backend/src/metering/ingestion.py</code>:</p><ul><li><strong>Functional Requirements</strong>: <ol><li>Ingest raw consumption events (API calls, storage, compute seconds) with client-supplied idempotency keys.</li><li>Rate usage against tiered, volume, graduated, and flat-rate price books.</li><li>Close billing periods, aggregate rollups, and generate immutable invoices with gapless legal numbering (<code>INV-YYYY-XXXX</code>).</li><li>Enforce double-entry accounting where $\\sum \\text{Debits} == \\sum \\text{Credits}$.</li></ol></li><li><strong>Non-Functional Requirements</strong>: <ol><li>High availability: 99.95% uptime for ingestion endpoints.</li><li>Latency: p95 ingestion latency $&lt;25\\text{ms}$; rating calculation $&lt;5\\text{ms}$.</li><li>Strict consistency: Zero duplicate events and zero floating-point rounding drift.</li></ol></li></ul><hr><h2 id="_3-mathematical-capacity-estimation" tabindex="-1">3. Mathematical Capacity Estimation <a class="header-anchor" href="#_3-mathematical-capacity-estimation" aria-label="Permalink to &quot;3. Mathematical Capacity Estimation&quot;">​</a></h2>',9)),(t(),l(u,null,{default:i(()=>[c(n,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Daily%5B10M%20Events%20%2F%20Day%5D%20--%3E%20Ingestion%5B~116%20Events%20%2F%20Sec%20Steady%5D%0A%20%20%20%20Ingestion%20--%3E%20Peak%5B~500%20Events%20%2F%20Sec%20Peak%5D%0A%20%20%20%20Peak%20--%3E%20Storage%5B~3.5%20GB%20%2F%20Day%20Storage%5D%0A%20%20%20%20Storage%20--%3E%20Annual%5B~1.28%20TB%20%2F%20Year%20Partitioned%20Storage%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="ingestion-throughput" tabindex="-1">Ingestion Throughput <a class="header-anchor" href="#ingestion-throughput" aria-label="Permalink to &quot;Ingestion Throughput&quot;">​</a></h3><ul><li><strong>Daily Event Volume</strong>: 10,000,000 events/day across 1,000 active tenants.</li><li><strong>Average QPS</strong>: $$\\text{QPS}_{\\text{avg}} = \\frac{10,000,000 \\text{ events}}{86,400 \\text{ seconds}} \\approx 116 \\text{ events/second}$$</li><li><strong>Peak Load (5x Multiplier)</strong>: $$\\text{QPS}_{\\text{peak}} = 116 \\times 5 = 580 \\text{ events/second}$$</li></ul><h3 id="storage-calculations" tabindex="-1">Storage Calculations <a class="header-anchor" href="#storage-calculations" aria-label="Permalink to &quot;Storage Calculations&quot;">​</a></h3><ul><li><strong>Raw Event Payload Size</strong>: <ul><li><code>event_id</code>: 64 bytes</li><li><code>tenant_id</code>: 64 bytes</li><li><code>customer_id</code>: 64 bytes</li><li><code>event_type</code>: 32 bytes</li><li><code>quantity</code>: 8 bytes (<code>BIGINT</code>)</li><li><code>idempotency_key</code>: 64 bytes</li><li><code>timestamp</code>: 8 bytes (<code>TIMESTAMP</code>)</li><li><code>dimensions_json</code>: ~100 bytes</li><li>Indexes &amp; Overhead: ~150 bytes</li><li><strong>Total per Event</strong>: $\\approx 350 \\text{ bytes}$</li></ul></li><li><strong>Daily Storage Influx</strong>: $$\\text{Daily Storage} = 10,000,000 \\times 350 \\text{ bytes} \\approx 3.5 \\text{ GB/day}$$</li><li><strong>Annual Storage Footprint</strong>: $$\\text{Annual Storage} = 3.5 \\text{ GB} \\times 365 \\approx 1.28 \\text{ TB/year}$$</li></ul><hr><h2 id="_4-what-breaks-first-at-10x-100x-and-1000x-load" tabindex="-1">4. What Breaks First at 10x, 100x, and 1000x Load <a class="header-anchor" href="#_4-what-breaks-first-at-10x-100x-and-1000x-load" aria-label="Permalink to &quot;4. What Breaks First at 10x, 100x, and 1000x Load&quot;">​</a></h2><ul><li><strong>At 10x Load (1,160 QPS)</strong>: PostgreSQL B-tree index maintenance slows down; database connection pool hits limits. Remediated by increasing pool size and tuning write-ahead log (WAL) buffers.</li><li><strong>At 100x Load (11,600 QPS)</strong>: Synchronous database inserts saturate disk write IOPS. Remediated by introducing an Apache Kafka streaming buffer.</li><li><strong>At 1000x Load (116,000 QPS)</strong>: Single PostgreSQL instance cannot write 350 GB/day. Remediated by horizontally sharding usage event tables by <code>tenant_id</code> hash across distinct database nodes.</li></ul><hr><h2 id="_5-30-second-interview-answer" tabindex="-1">5. 30-Second Interview Answer <a class="header-anchor" href="#_5-30-second-interview-answer" aria-label="Permalink to &quot;5. 30-Second Interview Answer&quot;">​</a></h2><blockquote><p>&quot;I modeled our billing engine around a daily ingestion volume of 10 million events, translating to an average of 116 requests per second and peak bursts of 580 QPS. At 350 bytes per indexed record, the usage ledger accumulates approximately 3.5 GB of data per day, or 1.28 TB per year. To prevent performance degradation over time, I implemented monthly range partitioning in PostgreSQL, allowing the database engine to isolate active writes to the current month&#39;s partition while archiving historical data.&quot;</p></blockquote>',10))])}const S=o(m,[["render",g]]);export{f as __pageData,S as default};
